package com.company.skillplatform.version.infrastructure.repository;import com.company.skillplatform.version.domain.LifecycleStatus;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import java.util.*;import org.springframework.data.jpa.repository.*;
public interface SkillVersionRepository extends JpaRepository<SkillVersionEntity,Long>{List<SkillVersionEntity> findBySkillIdOrderByTimeCreatedDesc(Long skillId);List<SkillVersionEntity> findByLifecycleStatus(LifecycleStatus status);Optional<SkillVersionEntity> findFirstBySkillIdAndLifecycleStatusInOrderByPublishedAtDesc(Long skillId,Collection<LifecycleStatus> statuses);@Modifying(clearAutomatically=true,flushAutomatically=true)@Query("update SkillVersionEntity v set v.versionNo=v.versionNo+1 where v.id=:id and v.versionNo=:versionNo")int incrementVersion(Long id,int versionNo);}
